package com.blog.mapper;
import com.blog.dto.*; import com.blog.entity.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class BlogMapper { public AuthDtos.UserResponse user(User u){return new AuthDtos.UserResponse(u.getId(),u.getUsername(),u.getEmail(),u.getRole().name(),u.getFirstName(),u.getLastName(),u.getCreatedAt());} public CategoryDtos.CategoryResponse category(Category c){return c==null?null:new CategoryDtos.CategoryResponse(c.getId(),c.getName(),c.getDescription());} public PostDtos.PostResponse post(Post p){return new PostDtos.PostResponse(p.getId(),p.getTitle(),p.getSlug(),p.getContent(),p.getImageUrl(),p.isPublished(),p.getCreatedAt(),p.getUpdatedAt(),user(p.getAuthor()),category(p.getCategory()));} public CommentDtos.CommentResponse comment(Comment c){return new CommentDtos.CommentResponse(c.getId(),c.getContent(),c.getCreatedAt(),user(c.getUser()),c.getReplies().stream().map(this::comment).toList());} }
